secureCode.code:
// SECURE - the pattern is BOUND; UNION / sqlite_master become 'text to search for'
const rows = db
  .prepare("SELECT title, body FROM articles WHERE title LIKE ?")
  .all('%' + q + '%');
// Defense in depth: least privilege - the app account should reach only the tables it needs.

